package com.mis.mis_backend.subject;import jakarta.persistence.*;@Entity @Table(name="subjects") public class Subject{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="subject_id") private Integer subjectId;@Column(name="course_id") private Integer courseId;@Column(name="faculty_id") private Integer facultyId;@Column(name="subject_code") private String subjectCode;@Column(name="subject_name") private String subjectName;private Integer semester;private Integer credits;public Subject(){} public Integer getSubjectId(){return subjectId;} public Integer getCourseId(){return courseId;} public void setCourseId(Integer v){courseId=v;} public Integer getFacultyId(){return facultyId;} public void setFacultyId(Integer v){facultyId=v;} public String getSubjectCode(){return subjectCode;} public void setSubjectCode(String v){subjectCode=v;} public String getSubjectName(){return subjectName;} public void setSubjectName(String v){subjectName=v;} public Integer getSemester(){return semester;} public void setSemester(Integer v){semester=v;} public Integer getCredits(){return credits;} public void setCredits(Integer v){credits=v;}}